    const TARGET = 'PYTHON';
    const game = {
      letters: Array.from(TARGET).map(() => { let c = { revealed: false, char: '_' }; c.reveal = () => { c.revealed = true; return c.char; }; return c; }),
      state: { won: false, lost: false },
      guess: (char) => {
        if (game.state.won || game.state.lost) return;
        for (const l of game.letters) if (l.char === char) { l.reveal(); if (game.letters.every((c) => c.revealed)) game.state.won = true; }
      },
      checkWin: () => game.state.won,
      checkLoss: () => game.state.lost,
    };
    const render = () => {
      const lettersDiv = document.querySelector('.letters');
      lettersDiv.innerHTML = '';
      for (const l of game.letters) {
        const letter = document.createElement('div');
        letter.className = 'letter';
        letter.textContent = l.revealed ? l.reveal() : '_';
        lettersDiv.appendChild(letter);
      }
      const status = document.getElementById('status');
      if (game.checkWin()) { status.textContent = 'You won!'; status.className = 'win'; } else if (game.checkLoss()) { status.textContent = 'You lost!'; status.className = 'lose'; }
    };
    const guess = (char) => {
      game.guess(char);
      render();
    };
    for (const char of TARGET) guess(char);
    render();
  </script>
