export interface Move { row: number; col: number }
export class Game {
  private board: string[][];
  constructor() { this.board = Array.from({ length: 3 }, () => new Array(3).fill('')); }
  private checkVictory() {
    const lines = [
      this.board[0],
      this.board[1],
      this.board[2],
      this.board[0][0] + this.board[1][0] + this.board[2][0],
      this.board[0][1] + this.board[1][1] + this.board[2][1],
      this.board[0][2] + this.board[1][2] + this.board[2][2],
      this.board[0][0] + this.board[1][1] + this.board[2][2],
      this.board[0][2] + this.board[1][1] + this.board[2][0],
    ];
    return lines.some((line) => (line.includes('X') && line.includes('O') ? null : line.includes('X') ? 'X' : line.includes('O') ? 'O' : null));
  }
  get availableMoves() { return this.board.map((row, i) => row.map((cell, j) => cell === '' ? { row: i, col: j } : null).filter(Boolean)).flat(); }
  move(row: number, col: number, player: 'X' | 'O') {
    if (this.board[row][col] !== '') return false;
    this.board[row][col] = player;
    return this.checkVictory();
  }
}
export function minimax(board: string[][], depth: number, isMaximizing: boolean, player: 'X' | 'O', alpha: number, beta: number) {
  const winner = board.find((row) => row.every((cell) => cell === player));
  if (winner) return isMaximizing ? 10 : -10;
  if (!board.some((row) => row.some((cell) => cell === ''))) return 0;
  let value = -Infinity;
  for (const { row, col } of new Game().availableMoves) {
    board[row][col] = player;
    const score = minimax(board, depth - 1, !isMaximizing, player === 'X' ? 'O' : 'X', alpha, beta);
    board[row][col] = '';
    value = Math.max(value, score);
    alpha = Math.max(alpha, value);
    if (beta <= alpha) break;
  }
  return value;
}
