export class TicTacToe {
  private game: Game;
  private status: string;
  private board: string[] = new Array(9).fill('');
  private currentPlayer: 'x' | 'o';

  constructor() {
    this.game = new Game();
    this.status = 'Your turn';
    this.currentPlayer = 'x';
  }

  handleCellClick(index: number): void {
    if (this.board[index] || this.game.isGameOver()) return;
    this.board[index] = this.currentPlayer;
    this.currentPlayer = this.currentPlayer === 'x' ? 'o' : 'x';
    this.game.update(this.board);
    if (this.game.isGameOver()) {
      this.status = this.game.getWinner() === '' ? 'Draw' : `Player ${this.game.getWinner()} wins!`;
      this.board.fill('');
      this.currentPlayer = 'x';
    } else {
      if (this.currentPlayer === 'o') {
        const move = this.game.minimax(this.board);
        this.board[move] = 'o';
        this.currentPlayer = 'x';
      }
    }
  }

  getBoard(): string[] { return this.board; }
  getStatus(): string { return this.status; }
}
