export function renderBars(data: number[], ctx: CanvasRenderingContext2D) {
  ctx.clearRect(0, 0, canvasWidth, canvasHeight);
  const barScale = canvasWidth / (data.length + 1);
  data.forEach((height, i) => {
    const x = barSpacing + i * barScale;
    const y = canvasHeight - height;
    ctx.fillStyle = 'steelblue';
    ctx.fillRect(x, y, barScale - barSpacing, height);
    ctx.strokeStyle = 'black';
    ctx.strokeRect(x, y, barScale - barSpacing, height);
  });
}

export async function runSort(sortName: 'bubble' | 'quick' | 'merge', data: number[], speedMs: number) {
  const sort: (data: number[]) => number[] = { bubble: bubbleSort, quick: quickSort, merge: mergeSort }[sortName];
  const sorted = await sort(data);
  let i = 0;
  return new Promise<void>((resolve) => {
    const interval = setInterval(() => {
      if (i >= data.length) {
        clearInterval(interval);
        resolve();
        return;
      }
      renderBars(sorted.slice(0, i + 1), document.getElementById('canvas')!.getContext('2d')!);
      i++;
    }, speedMs);
  });
}
