export function renderBars(bars: Bar[], width: number, height: number): string {
  const barWidth = (width - 10) / bars.length;
  let html = '<svg viewBox="0 0 600 400" xmlns="http://www.w3.org/2000/svg"><g>';
  bars.forEach((bar) => {
    const rect = `rect ${bar.index * barWidth + 5} 399 ${barWidth} -${bar.height}`;
    html += `<g><title>${bar.value}</title><rect ${rect} style="fill:${bar.color || 'blue'}" /><text x="${bar.index * barWidth + 5}" y="380" fill="black">${bar.value}</text></g>`;
  });
  html += '</g></svg>';
  return html;
