# ===== src/sorts.ts =====
```typescript
export function bubbleSort(arr: number[], animate: (i: number) => void) {
  const n = arr.length;
  for (let i = 0; i < n - 1; i++) {
    for (let j = 0; j < n - 1 - i; j++) {
      if (arr[j] > arr[j + 1]) {
        const temp = arr[j];
        arr[j] = arr[j + 1];
        arr[j + 1] = temp;
        animate(j + 1);
      }
    }
  }
}

export function quickSort(arr: number[], lo: number, hi: number, animate: (i: number) => void) {
  if (lo >= hi) return;
  const pivot = partition(arr, lo, hi, animate);
  quickSort(arr, lo, pivot - 1, animate);
  quickSort(arr, pivot + 1, hi, animate);
}

function partition(arr: number[], lo: number, hi: number, animate: (i: number) => void) {
  const pivot = arr[hi];
  let i = lo - 1;
  for (let j = lo; j < hi; j++) {
    if (arr[j] <= pivot) {
      i++;
      const temp = arr[i];
      arr[i] = arr[j];
      arr[j] = temp;
      animate(i);
    }
  }
  const temp = arr[i + 1];
  arr[i + 1] = arr[hi];
  arr[hi] = temp;
  animate(i + 1);
  return i + 1;
}

export function mergeSort(arr: number[], animate: (i: number) => void) {
  const temp = new Array(arr.length);
  const merge = (left: number, mid: number, right: number) => {
    let i = left, j = mid, k = left;
    while (i < mid && j <= right) {
      if (arr[i] <= arr[j]) temp[k++] = arr[i++];
      else temp[k++] = arr[j++];
      animate(k - 1);
    }
    while (i < mid) temp[k++] = arr[i++];
    while (j <= right) temp[k++] = arr[j++];
    for (let p = left; p <= right; p++) arr[p] = temp[p];
  };
  const sort = (left: number, right: number) => {
    if (right - left <= 0) return;
    const mid = (left + right) >> 1;
    sort(left, mid);
    sort(mid + 1, right);
    merge(left, mid + 1, right);
  };
  sort(0, arr.length - 1);
}
