export function drawOnCanvas(event: MouseEvent) {
  const canvas = document.getElementById('canvas') as HTMLCanvasElement;
  const ctx = canvas.getContext('2d');
  if (!ctx) return;
  ctx.beginPath();
  ctx.moveTo(event.offsetX, event.offsetY);
  ctx.lineTo(event.offsetX, event.offsetY);
  ctx.stroke();
}

export function handleColorChange(color: string) {
  const palette = document.getElementById('palette') as HTMLDivElement;
  const swatches = palette.getElementsByClassName('swatch') as HTMLCollectionOf<HTMLElement>;
  for (const swatch of swatches) {
    if (swatch.style.backgroundColor === color) {
      swatch.classList.add('selected');
    } else {
      swatch.classList.remove('selected');
    }
  }
}

export function handleBrushSize(size: number) {
  const brushSize = document.getElementById('brushSize') as HTMLInputElement;
  if (brushSize) brushSize.value = size.toString();
}
