    let currentPlayer = 'X';
    let gameWon = false;

    function togglePlayer() { currentPlayer = currentPlayer === 'X' ? 'O' : 'X'; }
    function checkWin() {
      const winningCombinations = [
        [0, 1, 2], [3, 4, 5], [6, 7, 8], // rows
        [0, 3, 6], [1, 4, 7], [2, 5, 8], // columns
        [0, 4, 8], [2, 4, 6]             // diagonals
      ];
      for (const combo of winningCombinations) {
        if ([cells[combo[0]], cells[combo[1]], cells[combo[2]]].every(c => c.textContent.trim() === currentPlayer)) {
          gameWon = true;
          return combo;
        }
      }
      return null;
    }
    cells.forEach((cell, idx) => {
      cell.addEventListener('click', () => {
        if (cell.textContent.trim() || gameWon) return;
        cell.textContent = currentPlayer;
        const win = checkWin();
        if (win) {
          const line = document.getElementById('win-line');
          line.style.transform = `translate(${win[0] * 110}px, 0)`;
          line.style.display = 'block';
          line.style.border = `10px solid red`;
