<script>
class Grid {
  constructor(cols, rows) {
    this.cols = cols;
    this.rows = rows;
    this.grid = Array.from({ length: rows }, () => Array(cols).fill(false));
  }
  draw() {
    const container = document.querySelector('.grid-container');
    container.innerHTML = '';
    for (let y = 0; y < this.rows; y++) {
      for (let x = 0; x < this.cols; x++) {
        const cell = document.createElement('div');
        cell.className = this.grid[y][x] ? 'cell alive' : 'cell';
        cell.setAttribute('data-x', x);
        cell.setAttribute('data-y', y);
        cell.addEventListener('click', () => this.toggleCell(x, y));
        container.appendChild(cell);
      }
    }
  }
  toggleCell(x, y) {
    this.grid[y][x] = !this.grid[y][x];
  }
  next() {
    const next = Array.from({ length: this.rows }, () => Array(this.cols).fill(false));
    for (let y = 0; y < this.rows; y++) {
      for (let x = 0; x < this.cols; x++) {
        let liveNeighbors = 0;
        for (let dy = -1; dy <= 1; dy++) {
          for (let dx = -1; dx <= 1; dx++) {
            if (dx === 0 && dy === 0) continue;
            const ny = y + dy, nx = x + dx;
            if (nx >= 0 && nx < this.cols && ny >= 0 && ny < this.rows) {
              liveNeighbors += this.grid[ny][nx];
            }
          }
        }
        if (this.grid[y][x] && liveNeighbors < 2) next[y][x] = false;
        else if (this.grid[y][x] && liveNeighbors > 3) next[y][x] = false;
        else if (!this.grid[y][x] && liveNeighbors === 3) next[y][x] = true;
      }
    }
    return next;
  }
}

const cols = 50, rows = 30;
const grid = new Grid(cols, rows);
grid.draw();

let generation = 0;
let isRunning = false;

const cells = document.querySelectorAll('.cell');
const startButton = document.getElementById('start');
const stepButton = document.getElementById('step');
const clearButton = document.getElementById('clear');

function start() {
  if (isRunning) return;
  isRunning = true;
  stepButton.disabled = true;
  clearButton.disabled = true;
  startButton.innerText = 'Pause';
  const interval = setInterval(() => {
    generation++;
    cells.forEach(cell => cell.classList.remove('alive'));
    grid.grid.forEach((row, y) => {
      row.forEach((alive, x) => {
        if (alive) cells[y * cols + x].classList.add('alive');
      });
    });
    grid.grid = grid.next();
  }, 100);
}

function step() {
  if (!isRunning) return;
  generation++;
  cells.forEach(cell => cell.classList.remove('alive'));
  grid.grid.forEach((row, y) => {
    row.forEach((alive, x) => {
      if (alive) cells[y * cols + x].classList.add('alive');
    });
  });
  grid.grid = grid.next();
}

function clear() {
  cells.forEach(cell => cell.classList.remove('alive'));
  cells.forEach(cell => grid.grid[cell.dataset.y][cell.dataset.x] = false);
  generation = 0;
}

startButton.addEventListener('click', start);
stepButton.addEventListener('click', step);
clearButton.addEventListener('click', clear);
</script>
