export function findPath(algo: string, startX: number, startY: number, endX: number, endY: number): number[] {
  const queue: Array<{ x: number; y: number; path: number[] }> = [{ x: startX, y: startY, path: [startX, startY] }];
  const visited: Record<string, boolean> = { [startX + ',' + startY]: true };
  const grid = Array.from(document.querySelectorAll('.grid .cell')) as unknown as HTMLElement[][];

  const cells: Record<string, { x: number; y: number; visited: boolean }> = {};
  for (let i = 0; i < grid.length; i++) {
    const x = i % 10;
    const y = (i / 10) | 0;
    cells[i] = { x, y, visited: false };
  }
  if (algo === 'bfs') {
    while (queue.length) {
      const { x, y, path } = queue.shift()!;
      const cur = cells[x * 10 + y];
      if (cur.x === endX && cur.y === endY) {
        return path.slice(0, path.length - 1);
      }
      for (const [dx, dy] of [[0, 1], [0, -1], [1, 0], [-1, 0]]) {
        const nx = x + dx;
        const ny = y + dy;
        if (nx >= 0 && nx < 10 && ny >= 0 && ny < 10 && !cells[nx * 10 + ny].visited) {
          cells[nx * 10 + ny].visited = true;
          queue.push({ x: nx, y: ny, path: path.concat(nx * 10 + ny) });
        }
      }
    }
  }
  return [];
}
