export function gcd(a: number, b: number): number {
  while (b !== 0) {
    let temp = b;
    b = a % b;
    a = temp;
  }
  return a;
}

export function isPrime(n: number): boolean {
  if (n <= 1) return false;
  for (let i = 2; i * i <= n; i++) {
    if (n % i === 0) return false;
  }
  return true;
}

function legalFrom(r, c) {
  const p = boardState[r][c]; if (!p) return [];
  const out = [];
  for (const mv of pseudoLegal(r, c)) {
    const target = applyMove(r, c, mv);
    const ok = !inCheck(p.color);
    undoMove(r, c, mv, target);
    if (ok) out.push(mv);
  }
  return out;
}
function applyMove(r, c, mv) {
  const p = boardState[r][c];
  const target = mv.capture ? boardState[mv.r][mv.c] : null;
  if (mv.enPassant) { const pr = mv.r + (p.color === 'white' ? 1 : -1); boardState[pr][mv.c] = null; }
  if (mv.castle === 'k') { const h = p.color === 'white' ? 7 : 0; boardState[h][5] = boardState[h][7]; boardState[h][7] = null; }
  if (mv.castle === 'q') { const h = p.color === 'white' ? 7 : 0; boardState[h][3] = boardState[h][0]; boardState[h][0] = null; }
  boardState[mv.r][mv.c] = p;
  boardState[r][c] = null;
  return target;
}
function undoMove(r, c, mv, target) {
  const p = boardState[mv.r][mv.c];
  boardState[r][c] = p;
  boardState[mv.r][mv.c] = target !== undefined ? target : null;
  if (mv.enPassant) { const pr = mv.r + (p.color === 'white' ? 1 : -1); boardState[pr][mv.c] = { type: 'pawn', color: p.color === 'white' ? 'black' : 'white' }; }
  if (mv.castle === 'k') { const h = p.color === 'white' ? 7 : 0; boardState[h][7] = boardState[h][5]; boardState[h][5] = null; }
  if (mv.castle === 'q') { const h = p.color === 'white' ? 7 : 0; boardState[h][0] = boardState[h][3]; boardState[h][3] = null; }
}
function minimax(depth, isMax) {
  const color = isMax ? 'white' : 'black';
  const moves = allLegal(color);
  if (moves.length === 0) return isMax ? -99999 : 99999;
  if (depth === 0) return evaluate();
  let best = isMax ? -Infinity : Infinity;
  for (const { r, c, mv } of moves) {
    const target = applyMove(r, c, mv);
    const v = minimax(depth - 1, !isMax);
    undoMove(r, c, mv, target);
    if (isMax) best = Math.max(best, v); else best = Math.min(best, v);
  }
  return best;
}

