  <script>
    const canvas = document.getElementById('canvas');
    const ctx = canvas.getContext('2d');
    const cells = Array.from({ length: 256 }, () => Array.from({ length: 16 }, () => '#000000'));
    const colorPicker = document.getElementById('colorPicker');
    const saveBtn = document.getElementById('saveBtn');
    const loadBtn = document.getElementById('loadBtn');

    function draw() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      ctx.fillStyle = '#fff';
      ctx.fillRect(0, 0, canvas.width, canvas.height);
      ctx.fillStyle = '#000';
      cells.forEach((row) => {
        row.forEach((color, i) => {
          const x = i % 16; const y = Math.floor(i / 16);
          ctx.fillStyle = color;
          ctx.fillRect(x * 16, y * 16, 16, 16);
        });
      });
    }

    function save() {
      localStorage.setItem('canvas', JSON.stringify(cells));
      alert('Canvas saved.');
    }

    function load() {
      const loadedCells = localStorage.getItem('canvas') ? JSON.parse(localStorage.getItem('canvas')!) : cells;
      cells.splice(0, cells.length, ...loadedCells);
      draw();
      alert('Canvas loaded.');
    }

    colorPicker.addEventListener('input', () => {
      cells.forEach((row) => {
        row.fill(colorPicker.value);
      });
      draw();
    });

    draw();
  </script>
</body>
