  <style>
    .grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 12px; }
    .cell { border: 1px solid #ddd; padding: 8px; border-radius: 4px; }
    .formula { border-bottom: 2px dashed #aaa; }
  </style>
</head>
<body>
  <div class="app">
    <div class="row">
      <div class="col">
        <input type="text" id="formula" placeholder="=A1+B1" />
      </div>
      <div class="col">
        <div class="grid" id="spreadsheet"></div>
      </div>
    </div>
    <div id="statusMsg"></div>
  </div>
  <script>
    const cells = [
      ['A1', '10'],
      ['B1', '20'],
      ['C1', '30']
    ];
    const spreadsheet = document.getElementById('spreadsheet');
    cells.forEach((cell) => {
      const div = document.createElement('div');
      div.classList.add('cell');
      if (cell[0] === 'A1') div.classList.add('formula');
      div.textContent = cell[1];
      spreadsheet.appendChild(div);
    });
    function evalFormula() {
      const formula = document.getElementById('formula').value;
      const cells = document.querySelectorAll('.cell');
      cells.forEach((c) => {
        const value = c.textContent;
        if (value.includes('=')) {
          try {
            c.textContent = eval(value.slice(1));
          } catch (e) {
            c.textContent = 'ERR';
          }
        }
      });
    }
    document.getElementById('formula').addEventListener('input', evalFormula);
  </script>
</body>
</html>
