# ===== spreadsheet.ts =====
```typescript
export class Cell { value: string; constructor(value: string) { this.value = value; } }
export class Spreadsheet {
  private cells: Cell[] = [];
  constructor(cells: string[]) {
    cells.forEach((v) => this.cells.push(new Cell(v)));
  }
  getCellById(id: string): Cell | undefined {
    return this.cells.find((c) => c.value.includes(id));
  }
}
